<?php
declare(strict_types=1);
require_once __DIR__.'/mill_recovery_core.php';

const TT_MC_ACCOUNTS = TT_DATA_DIR . '/accounts.json';
const TT_MC_OPERATIONS = TT_DATA_DIR . '/operations.json';
const TT_MC_MILLING_RATE = 3.0;

function mc_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function mc_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function mc_require_entity(array $u,string $entity,bool $write=false):void{if(($u['role']??'')==='Super Admin')return;$allowed=$write?(tt_user_can_access_entity($u,$entity,'Create')||tt_user_can_access_entity($u,$entity,'Edit')||tt_user_can_access_entity($u,$entity,'Approve')):tt_user_can_access_entity($u,$entity,'View');if(!$allowed)mc_out(['ok'=>false,'error'=>'You do not have permission for this legal entity.'],403);}
function mc_def():array{return ['revision'=>0,'journals'=>[],'events'=>[],'commodityBills'=>[],'managementCostingInputs'=>[],'managementCostingSheets'=>[],'managementCostingSheetHistory'=>[],'managementCostRates'=>[]];}
function mc_read_accounts():array{tt_ensure_data_dir();if(!is_file(TT_MC_ACCOUNTS))return mc_def();$h=fopen(TT_MC_ACCOUNTS,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=mr_decode_store((string)$raw,mc_def());return array_replace_recursive(mc_def(),$v);}
function mc_read_ops():array{if(!is_file(TT_MC_OPERATIONS))return ['values'=>[]];$h=fopen(TT_MC_OPERATIONS,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Operational storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}return mr_decode_store((string)$raw,['values'=>[]]);}
function mc_op(array $ops,string $key):array{$raw=$ops['values'][$key]??'';if(!is_string($raw)||$raw==='')return [];$v=json_decode($raw,true,512,JSON_THROW_ON_ERROR);if(!is_array($v)||!array_is_list($v))throw new RuntimeException('Invalid operational rows.');return $v;}
function mc_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))mc_out(['ok'=>false,'error'=>'Costing sheet is available for TTI / BRM.'],422);return $v;}
function mc_norm(string $v):string{$v=preg_replace('/[^A-Z0-9]+/i',' ',trim($v))??trim($v);return strtoupper(trim(preg_replace('/\s+/',' ',$v)??$v));}
function mc_variety(string $v):string{$u=mc_norm($v);if(str_contains($u,'IRRI 6'))$b='IRRI-6';elseif(str_contains($u,'1121'))$b='1121';elseif(str_contains($u,'PK 386'))$b='PK-386';elseif(str_contains($u,'SUPER KERNEL'))$b='SUPER KERNEL';elseif(str_contains($u,'D 98'))$b='D-98';elseif(preg_match('/(^| )C 9( |$)/',$u))$b='C-9';else$b=$u?:'RICE';if(str_contains($u,'PARBOIL')||str_contains($u,'SELLA'))$b.=' PARBOIL';return $b;}
function mc_product(string $v):string{$u=mc_norm($v);if(str_starts_with($u,'B2 CSR'))return 'B2 CSR';if(str_starts_with($u,'B2')||str_contains($u,'B2 SORTEX')||str_contains($u,'BROKEN B2'))return 'B2';if($u==='CSR'||str_starts_with($u,'CSR '))return 'CSR';if($u==='POWDER'||str_contains($u,' POWDER'))return 'POWDER';if($u==='PADDY'||str_contains($u,' PADDY'))return 'PADDY';if($u==='B3'||str_starts_with($u,'B3 '))return 'B3';if($u==='OTHER')return 'OTHER';return $u;}
function mc_waste(string $v):bool{$u=mc_norm($v);return str_contains($u,'STONE')||str_contains($u,'SUTLI')||str_contains($u,'DUST');}
function mc_date(string $v):string{return mr_valid_date($v)?$v:'';}
function mc_sheet_id(string $entity,string $date,string $variety):string{return 'MCS-'.substr(hash('sha256',$entity.'|'.$date.'|'.$variety),0,18);}
function mc_rate_id(string $sheet,string $product):string{return 'MGR-'.substr(hash('sha256',$sheet.'|'.mc_norm($product)),0,20);}

function mc_bill_values(array $s):array{$out=[];foreach((array)($s['commodityBills']??[]) as $bill){if(!is_array($bill)||($bill['status']??'')!=='Verified / Posted')continue;$alloc=(array)($bill['receiptAllocations']??[]);if(!$alloc)continue;$base=0.0;foreach($alloc as $a)$base+=max(0,(float)($a['provisionalAmount']??0));$value=round((float)($bill['finalCommodityValue']??0)+(float)($bill['brokerageGross']??0),2);if($value<=0)continue;$used=0.0;$keys=array_keys($alloc);$last=end($keys);foreach($alloc as $i=>$a){$key=trim((string)($a['sourceKey']??''));if($key==='')continue;$part=$i===$last?round($value-$used,2):round($value*($base>0?max(0,(float)($a['provisionalAmount']??0))/$base:1/max(1,count($alloc))),2);$used=round($used+$part,2);$out[$key]=['value'=>$part,'billId'=>(string)($bill['id']??'')];}}return $out;}
function mc_receipts(array $s):array{$final=mc_bill_values($s);$rows=[];foreach((array)($s['events']??[]) as $e){if(!is_array($e)||($e['eventType']??'')!=='COMMODITY_RECEIPT_ACCEPTED')continue;$j=$s['journals'][(string)($e['journalId']??'')]??null;if(!is_array($j))continue;$m=is_array($j['meta']??null)?$j['meta']:[];$kg=(float)($m['payableWeightKg']??0);if($kg<=0)continue;$src=(string)($e['sourceKey']??'');$f=$final[$src]??null;$rows[]=['entity'=>(string)($e['entity']??$j['entity']??'TTI'),'date'=>(string)($j['date']??''),'varietyKey'=>mc_variety((string)($m['variety']??'')),'kg'=>$kg,'value'=>$f?(float)$f['value']:(float)($j['totalDebit']??0),'final'=>$f!==null,'sourceKey'=>$src];}return $rows;}
function mc_production(array $ops,string $entity='TTI'):array {
 $groups=[];foreach(mc_op($ops,'tt30prod') as $p){if(!is_array($p)||strtoupper((string)($p['entity']??'TTI'))!==$entity)continue;if(!mr_input_rows($p)&&!mr_output_rows($p))continue;$date=mc_date((string)($p['date']??''));if(!$date)continue;$variety=(string)($p['sourceVariety']??$p['displayName']??$p['variety']??'Rice');$vk=mc_variety($variety);$id=$entity.'|'.$date.'|'.$vk;if(!isset($groups[$id]))$groups[$id]=['id'=>$id,'date'=>$date,'variety'=>$variety,'varietyKey'=>$vk,'inputKg'=>0.,'inputComplete'=>true,'requiresInputStockCost'=>false,'readyKg'=>0.,'outputs'=>[]];$groups[$id]['requiresInputStockCost']=$groups[$id]['requiresInputStockCost']||!in_array(strtoupper((string)($p['inputStage']??'RAW')),['','RAW'],true);$actual=mr_actual_input($p);$groups[$id]['inputKg']+=$actual??0;$groups[$id]['inputComplete']=$groups[$id]['inputComplete']&&$actual!==null&&$actual>0;foreach(mr_output_rows($p) as $r){$name=$r['product'];$ready=$r['kind']==='finished';if($ready)$groups[$id]['readyKg']+=$r['kg'];if(!isset($groups[$id]['outputs'][$name]))$groups[$id]['outputs'][$name]=['product'=>$name,'kg'=>0.,'ready'=>$ready];$groups[$id]['outputs'][$name]['kg']+=$r['kg'];}}
 foreach($groups as &$g){$g['inputKg']=round($g['inputKg'],3);$g['readyKg']=round($g['readyKg'],3);$g['outputs']=array_values($g['outputs']);}unset($g);uasort($groups,static fn($a,$b)=>strcmp($a['date'],$b['date'])?:strcmp($a['varietyKey'],$b['varietyKey']));return $groups;
}

function mc_sales(array $ops,string $entity='TTI'):array{$rows=[];$n=0;foreach(mc_op($ops,'tt35localsales') as $x){if(!is_array($x)||strtoupper((string)($x['entity']??'TTI'))!==$entity)continue;$rate=(float)($x['rate']??0);$date=mc_date((string)($x['date']??$x['saleDate']??''));$product=trim((string)($x['product']??''));if($rate<=0||$date===''||$product==='')continue;$rows[]=['date'=>$date,'order'=>$n++,'rate'=>$rate,'product'=>$product,'key'=>mc_product($product),'reference'=>(string)($x['soda']??''),'party'=>(string)($x['party']??''),'source'=>'Mill Local Sale'];}foreach(mc_op($ops,'tt35exportersale') as $x){if(!is_array($x)||strtoupper((string)($x['entity']??'TTI'))!==$entity)continue;$rate=(float)($x['rate']??0);$date=mc_date((string)($x['date']??''));$product=trim((string)($x['product']??$x['brand']??''));if($rate<=0||$date===''||$product==='')continue;$keys=array_unique(array_filter([mc_product($product),mc_product((string)($x['brand']??''))]));foreach($keys as $key)$rows[]=['date'=>$date,'order'=>$n++,'rate'=>$rate,'product'=>$product,'key'=>$key,'reference'=>(string)($x['ref']??''),'party'=>(string)($x['buyer']??''),'source'=>'Mill Sale to Exporter'];}return $rows;}
function mc_last_sale(array $sales,string $product,string $date):?array{$key=mc_product($product);$best=null;foreach($sales as $s){if(($s['key']??'')!==$key||($s['date']??'')>$date)continue;if($best===null||$s['date']>$best['date']||($s['date']===$best['date']&&$s['order']>$best['order']))$best=$s;}return $best;}
function mc_director_input(array $s,string $entity,string $date,string $vk):?array{$best=null;foreach((array)($s['managementCostingInputs']??[]) as $x){if(!is_array($x)||($x['entity']??'')!==$entity||($x['date']??'')!==$date)continue;$xv=mc_variety((string)($x['variety']??$x['varietyKey']??''));if($xv!==$vk)continue;$best=$x;}return $best;}

function mc_build(array $s,array $ops,string $entity):array{$groups=mc_production($ops,$entity);$receipts=array_values(array_filter(mc_receipts($s),static fn($r)=>($r['entity']??'TTI')===$entity));$sales=mc_sales($ops,$entity);$events=[];foreach($receipts as $r)$events[]=['date'=>$r['date'],'p'=>0,'kind'=>'R','data'=>$r];foreach($groups as $g)$events[]=['date'=>$g['date'],'p'=>1,'kind'=>'P','data'=>$g];usort($events,static fn($a,$b)=>strcmp((string)$a['date'],(string)$b['date'])?:($a['p']<=>$b['p']));$pool=[];$sheets=[];$uncertain=[];foreach($events as $e){if($e['kind']==='R'){$r=$e['data'];$k=$r['varietyKey'];if(!isset($pool[$k]))$pool[$k]=['kg'=>0.0,'value'=>0.0,'provisionalKg'=>0.0];$pool[$k]['kg']+=(float)$r['kg'];$pool[$k]['value']+=(float)$r['value'];if(empty($r['final']))$pool[$k]['provisionalKg']+=(float)$r['kg'];continue;}$g=$e['data'];$k=$g['varietyKey'];$st=$pool[$k]??['kg'=>0.0,'value'=>0.0,'provisionalKg'=>0.0];$avg=$st['kg']>0?$st['value']/$st['kg']:0;$poolWasUncertain=!empty($uncertain[$k]);if(empty($g['inputComplete'])||!empty($g['requiresInputStockCost']))$uncertain[$k]=true;$need=(float)$g['inputKg'];$enough=$st['kg']+.001>=$need;$consume=min($need,(float)$st['kg']);$provisional=$st['kg']>0?(float)$st['provisionalKg']*($consume/$st['kg']):0;if($consume>0){$st['kg']-=$consume;$st['value']-=$consume*$avg;$st['provisionalKg']=max(0,$st['provisionalKg']-$provisional);$pool[$k]=$st;}$input=mc_director_input($s,$entity,$g['date'],$k);$rawRate=(float)($input['rawRiceRate']??0);$rawSource=$rawRate>0?'Directors Daily Costing':($provisional>.001?'Purchase Cost — partly provisional':'Purchase Cost');if($rawRate<=0)$rawRate=$avg;$millRate=(float)($input['millingRate']??0);$millSource=$millRate>0?'Directors Daily Costing':'Fallback Rs 3/kg';if($millRate<=0)$millRate=TT_MC_MILLING_RATE;$rawValue=round($need*$rawRate,2);$millingValue=round($need*$millRate,2);$by=[];$byValue=0.0;$missing=[];foreach($g['outputs'] as $o){if(!empty($o['ready']))continue;$name=(string)$o['product'];$kg=(float)$o['kg'];if(mc_waste($name)){$by[]=['product'=>$name,'kg'=>$kg,'rate'=>0,'value'=>0,'rateSource'=>'Waste / Nil','saleDate'=>'','saleReference'=>'','party'=>''];continue;}$pk=mc_product($name);$directorRates=(array)($input['byProducts']??[]);$rate=isset($directorRates[$pk])?(float)$directorRates[$pk]:(isset($directorRates[$name])?(float)$directorRates[$name]:0);$src='';$saleDate='';$saleRef='';$party='';if($rate>0)$src='Directors Daily Costing';else{$sale=mc_last_sale($sales,$name,$g['date']);if($sale){$rate=(float)$sale['rate'];$src='Last Mill Sale';$saleDate=(string)$sale['date'];$saleRef=(string)$sale['reference'];$party=(string)$sale['party'];}}if($rate<=0){$missing[]=$pk;$by[]=['product'=>$name,'kg'=>$kg,'rate'=>null,'value'=>null,'rateSource'=>'No previous Mill sale','saleDate'=>'','saleReference'=>'','party'=>''];continue;}$value=round($kg*$rate,2);$byValue+=$value;$by[]=['product'=>$name,'kg'=>$kg,'rate'=>$rate,'value'=>$value,'rateSource'=>$src,'saleDate'=>$saleDate,'saleReference'=>$saleRef,'party'=>$party];}$readyValue=round($rawValue+$millingValue-$byValue,2);$readyRate=$g['readyKg']>0&&$readyValue>0?$readyValue/$g['readyKg']:0;$status='Ready';if(!empty($g['requiresInputStockCost']))$status='Waiting — reprocessing input-stock cost needs review';elseif(empty($g['inputComplete']))$status='Waiting — actual raw input is missing';elseif($poolWasUncertain)$status='Waiting — earlier production input is missing';elseif(!$enough)$status='Waiting — raw rice stock is short';elseif($rawRate<=0)$status='Waiting — raw rice cost is missing';elseif($g['readyKg']<=0)$status='Waiting — Ready Rice output is missing';elseif($missing)$status='Waiting — no previous Mill sale for '.implode(', ',array_values(array_unique($missing)));elseif($readyValue<=0)$status='Waiting — by-product value is too high';$sid=mc_sheet_id($entity,$g['date'],$k);$sheets[$sid]=['id'=>$sid,'entity'=>$entity,'date'=>$g['date'],'variety'=>$g['variety'],'varietyKey'=>$k,'inputKg'=>$need,'inputComplete'=>$g['inputComplete'],'readyRiceKg'=>$g['readyKg'],'readyProducts'=>array_values(array_map(static fn($o)=>(string)$o['product'],array_filter($g['outputs'],static fn($o)=>!empty($o['ready'])))),'rawRiceRate'=>round($rawRate,6),'rawRiceRateSource'=>$rawSource,'rawRiceValue'=>$rawValue,'usesProvisionalPurchaseCost'=>$provisional>.001,'millingRatePerKg'=>round($millRate,6),'millingRateSource'=>$millSource,'millingValue'=>$millingValue,'byProducts'=>$by,'byProductValue'=>round($byValue,2),'estimatedReadyRiceValue'=>$readyValue,'estimatedReadyRiceCostPerKg'=>!empty($g['inputComplete'])&&empty($g['requiresInputStockCost'])&&!$poolWasUncertain?round($readyRate,6):null,'missingByProductRates'=>array_values(array_unique($missing)),'status'=>$status,'ready'=>$status==='Ready','sourceMode'=>$input?'Directors / Fallback':'Fallback','note'=>'Live management costing sheet. Final Accounts stock cost remains separate.'];}return array_values($sheets);}
function mc_sync_management_rates(array &$s,array $sheets):void{$active=[];$perDate=[];foreach($sheets as $sh)if(!empty($sh['ready']))$perDate[$sh['date']][]=$sh;foreach($sheets as $sh){if(empty($sh['ready']))continue;$aliases=array_values(array_unique(array_merge((array)($sh['readyProducts']??[]),[(string)$sh['variety']] )));if(count($perDate[$sh['date']]??[])===1)$aliases[]='Ready Rice';$id=mc_rate_id($sh['id'],(string)$sh['variety']);$active[$id]=true;$s['managementCostRates'][$id]=['id'=>$id,'entity'=>$sh['entity'],'product'=>$sh['variety'],'aliases'=>array_values(array_unique($aliases)),'effectiveFrom'=>$sh['date'],'costPerKg'=>$sh['estimatedReadyRiceCostPerKg'],'inventoryAccount'=>'1320','status'=>'Active','source'=>'MANAGEMENT_COSTING_SHEET','costingSheetId'=>$sh['id'],'estimateOnly'=>true,'updatedAt'=>gmdate('c')];foreach((array)$sh['byProducts'] as $bp){if($bp['rate']===null||mc_waste((string)$bp['product']))continue;$bid=mc_rate_id($sh['id'],(string)$bp['product']);$active[$bid]=true;$s['managementCostRates'][$bid]=['id'=>$bid,'entity'=>$sh['entity'],'product'=>$bp['product'],'aliases'=>[mc_product((string)$bp['product'])],'effectiveFrom'=>$sh['date'],'costPerKg'=>$bp['rate'],'inventoryAccount'=>'1330','status'=>'Active','source'=>'MANAGEMENT_COSTING_SHEET','costingSheetId'=>$sh['id'],'estimateOnly'=>true,'updatedAt'=>gmdate('c')];}}foreach($s['managementCostRates'] as $id=>&$r)if(is_array($r)&&($r['entity']??'')===($sheets[0]['entity']??'')&&!isset($active[$id]))$r['status']='Superseded';unset($r);}
function mc_same_sheet(array $a,array $b):bool{foreach(['createdAt','updatedAt'] as $k){unset($a[$k],$b[$k]);}return json_encode($a,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)===json_encode($b,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
function mc_payload(array $s,array $ops,string $entity):array{$sheets=mc_build($s,$ops,$entity);usort($sheets,static fn($a,$b)=>strcmp((string)$b['date'],(string)$a['date'])?:strcmp((string)$a['variety'],(string)$b['variety']));return ['ok'=>true,'entity'=>$entity,'sheets'=>$sheets,'millingFallbackRate'=>TT_MC_MILLING_RATE,'serverNow'=>gmdate('c')];}
